          "최상위 타입은 적습니다. text, image, audio, video, application, 그리고 multipart와 font 같은 몇몇 특별한 것. 실제 정보를 나르는 것은 서브타입입니다. application/json은 구조화된 데이터, application/pdf는 문서, application/octet-stream은 “불투명한 바이트, 행운을 빕니다”를 뜻합니다. +접미어 관례들(application/+json, +xml)이 서브타입의 내부 구조를 표시합니다.",
