          "구분이 중요합니다. key는 키보드 레이아웃을 존중하고(프랑스 AZERTY에서 Tab 옆 키를 누르면 미국 QWERTY와 다른 key 값이 나옵니다) code는 언제나 같은 물리 위치를 식별합니다. 게임 조작과 단축키 시스템에는 보통 code가 옳고, 텍스트 처리에는 key가 옳습니다.",
